import { Inbox } from 'lucide-react';
import { Link } from 'react-router-dom';

import { Button } from '@/components/ui/button';
import { adminSpacing, adminTypography } from '@/lib/admin_spacing';
import { cn } from '@/lib/utils';
type EmptyStateVariant = 'default' | 'no-results' | 'blank-slate';

type EmptyStateProps = {
  title?: string;
  description?: string;
  variant?: EmptyStateVariant;
  actionLabel?: string;
  actionHref?: string;
  onAction?: () => void;
};

const variantDefaults: Record<EmptyStateVariant, { title: string; description: string }> = {
  default: {
    title: 'No data found',
    description: 'No records match the current view.',
  },
  'no-results': {
    title: 'No results',
    description: 'Nothing matches the current filters. Try adjusting or clearing them.',
  },
  'blank-slate': {
    title: 'Nothing here yet',
    description: 'Get started by creating your first record.',
  },
};

export function EmptyState({
  title,
  description,
  variant = 'default',
  actionLabel,
  actionHref,
  onAction,
}: EmptyStateProps) {
  const defaults = variantDefaults[variant];
  const resolvedTitle = title ?? defaults.title;
  const resolvedDescription = description ?? defaults.description;
  const showAction = Boolean(actionLabel && (actionHref || onAction));

  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center text-center',
        adminSpacing.gap.xl,
        adminSpacing.inset.emptyState
      )}
    >
      <div
        className={cn(
          'flex size-10 items-center justify-center rounded-[8px] border border-border/40 bg-muted/30 text-muted-foreground'
        )}
      >
        <Inbox aria-hidden className="size-5" />
      </div>
      <div className={cn('max-w-md', adminSpacing.stack.titleBlock)}>
        <p className={cn('whitespace-normal', adminTypography.sectionTitle)}>{resolvedTitle}</p>
        <p className={cn('whitespace-normal', adminTypography.bodyMuted)}>
          {resolvedDescription}
        </p>
      </div>
      {showAction ? (
        actionHref ? (
          <Button asChild variant="default">
            <Link to={actionHref}>{actionLabel}</Link>
          </Button>
        ) : (
          <Button type="button" variant="default" onClick={onAction}>
            {actionLabel}
          </Button>
        )
      ) : null}
    </div>
  );
}
